CREATE SCHEMA reader_test;
CREATE FUNCTION reader_test.assert(ok boolean,label text) RETURNS void LANGUAGE plpgsql AS $test$
BEGIN IF ok IS DISTINCT FROM true THEN RAISE EXCEPTION 'SURFACE_ASSERT_FAILED: %',label; END IF;
 RAISE NOTICE 'PRICE_SURFACE_PASS: %',label; END $test$;
CREATE FUNCTION reader_test.expect_error(command text,code text,label text) RETURNS void LANGUAGE plpgsql AS $test$
DECLARE actual text;
BEGIN
 BEGIN EXECUTE command; EXCEPTION WHEN OTHERS THEN GET STACKED DIAGNOSTICS actual=RETURNED_SQLSTATE; END;
 IF actual IS DISTINCT FROM code THEN RAISE EXCEPTION 'SURFACE_ERROR_EXPECTED: %, got %',label,actual; END IF;
 RAISE NOTICE 'PRICE_SURFACE_PASS: %',label;
END $test$;
