CREATE TABLE reader_test.saved_details AS SELECT details,manufacturer,part_number,engine,title,description FROM public.listings WHERE id=1001;
UPDATE public.listings SET details=details||'{"mileage":999999999999999999999.123456789,"model":["SECRET_ARRAY"],"color":true,"power":null,"unknown":"SECRET_UNKNOWN","engine":"wrong mirror"}'::jsonb WHERE id=1001;
SELECT reader_test.assert((EXISTS(SELECT 1 FROM jsonb_array_elements(public.get_public_listing_detail_v1('1001')->'item'->'details') x WHERE x->>'key'='mileage' AND x->>'value'='999999999999999999999.123456789')),'numeric_detail_text_exact');
SELECT reader_test.assert((EXISTS(SELECT 1 FROM jsonb_array_elements(public.get_public_listing_detail_v1('1001')->'item'->'details') x WHERE x->>'key'='color' AND x->>'value'='true')),'scalar_boolean_supported');
SELECT reader_test.assert((public.get_public_listing_detail_v1('1001')::text NOT LIKE '%SECRET_%'),'nested_unknown_excluded');
SELECT reader_test.assert(((SELECT count(*)=1 AND bool_and(x->>'value'='V8') FROM jsonb_array_elements(public.get_public_listing_detail_v1('1001')->'item'->'details') x WHERE x->>'key'='engine')),'canonical_attribute_not_stale_mirror');
UPDATE public.listings SET details=details||jsonb_build_object('brand',repeat('X',1001)),title=repeat('T',4097),description=repeat('D',32769) WHERE id=1001;
SELECT reader_test.assert((public.get_public_listing_detail_v1('1001')->'item'->>'details_truncated'='true' AND (SELECT char_length(x->>'value')=1000 FROM jsonb_array_elements(public.get_public_listing_detail_v1('1001')->'item'->'details') x WHERE x->>'key'='brand')),'detail_value_bounded_flag');
SELECT reader_test.assert((public.get_public_listing_detail_v1('1001')->'item'->>'title_truncated'='true' AND public.get_public_listing_detail_v1('1001')->'item'->>'description_truncated'='true' AND char_length(public.get_public_listing_detail_v1('1001')->'item'->>'title')=4096 AND char_length(public.get_public_listing_detail_v1('1001')->'item'->>'description')=32768),'fulltext_bounded_flags');
SELECT reader_test.assert(((SELECT char_length(title)=4097 AND char_length(description)=32769 AND char_length(details->>'brand')=1001 FROM public.listings WHERE id=1001)),'original_text_not_rewritten');
UPDATE public.listings l SET details=s.details,manufacturer=s.manufacturer,part_number=s.part_number,engine=s.engine,title=s.title,description=s.description FROM reader_test.saved_details s WHERE l.id=1001;
UPDATE public.listings SET price_kind='fixed',price_amount=999999999999999999.999,currency='KWD' WHERE id=1001;
SET LOCAL ROLE anon;
SELECT jsonb_build_object('detail',public.get_public_listing_detail_v1('1001'),'profile',public.get_public_profile_listings_v1('seller-a'),'search',public.search_public_listings_v2(p_search_query=>'surface-alpha'),'hidden',public.get_public_listing_detail_v1('1101'),'filtered',public.get_public_profile_listings_v1('seller-a','20000000-0000-4000-8000-000000000001'));
RESET ROLE;
REVOKE ALL ON FUNCTION public.get_public_listing_detail_v1(text),public.get_public_profile_listings_v1(text,uuid,integer,integer),public.search_public_listings_v2(text,text,text,text,text,text,integer,integer) FROM anon,authenticated;
SELECT reader_test.assert((NOT has_function_privilege('anon','public.get_public_listing_detail_v1(text)','EXECUTE')),'restore_closed_detail');
SELECT reader_test.assert((NOT has_function_privilege('authenticated','public.get_public_profile_listings_v1(text,uuid,integer,integer)','EXECUTE')),'restore_closed_profile');
SELECT 'PRICE_SURFACE_SUITE=PASS';
